INSERT INTO public.news ("id", "title", "date", "category", "badge", "badgeColor", "author", "summary", "content", "image") VALUES ('news-1', 'Projet Tramway 2029 : Les futures extensions vers l''Ouest et l''Est de Caen', '2026-02-15', 'Infrastructures', 'Projet Phare', 'emerald', 'Nolhanbj & Alexs_14', 'Caen la mer accélère sur le projet de prolongement du réseau de tramway à l''horizon 2029. De nouveaux quartiers seront reliés et de nouvelles rames sont attendues.', 'Le projet Tramway 2029 prévoit une nouvelle desserte structurante pour relier l''ouest caennais (vers le Chemin Vert et Saint-Contest) et l''est (vers la Presqu''île et Mondeville). Une commande complémentaire de rames Alstom Citadis est envisagée pour renforcer les fréquences sur le tronc commun central.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1000&q=80') ON CONFLICT ("id") DO UPDATE SET "title"=EXCLUDED."title", "date"=EXCLUDED."date", "category"=EXCLUDED."category", "badge"=EXCLUDED."badge", "badgeColor"=EXCLUDED."badgeColor", "author"=EXCLUDED."author", "summary"=EXCLUDED."summary", "content"=EXCLUDED."content", "image"=EXCLUDED."image";
INSERT INTO public.news ("id", "title", "date", "category", "badge", "badgeColor", "author", "summary", "content", "image") VALUES ('news-2', 'Transition Énergétique : 100% de la flotte de Lianes convertie au BioGNV', '2026-01-20', 'Flotte & Écologie', 'Verdissement', 'emerald', 'Alexs_14', 'Avec les dernières livraisons de bus Iveco Urbanway 12 et 18 GNV (séries 5200 et 7200), l''ensemble des Lianes 1, 2, 3 et 4 circule désormais avec une énergie propre.', 'La communauté urbaine Caen la mer poursuit avec succès son plan climat. Les bus alimentés en biométhane produit localement permettent une baisse drastique des émissions de particules fines et une réduction significative du bruit en centre-ville.', 'https://images.unsplash.com/photo-1570125909232-eb263c188f7e?auto=format&fit=crop&w=1000&q=80') ON CONFLICT ("id") DO UPDATE SET "title"=EXCLUDED."title", "date"=EXCLUDED."date", "category"=EXCLUDED."category", "badge"=EXCLUDED."badge", "badgeColor"=EXCLUDED."badgeColor", "author"=EXCLUDED."author", "summary"=EXCLUDED."summary", "content"=EXCLUDED."content", "image"=EXCLUDED."image";
INSERT INTO public.news ("id", "title", "date", "category", "badge", "badgeColor", "author", "summary", "content", "image") VALUES ('news-3', 'Ajustement du Réseau de Bus : Nouveaux itinéraires sur les lignes 11 et 20', '2025-09-01', 'Réseau & Horaires', 'Horaires', 'blue', 'Alexis', 'Pour la rentrée scolaire et universitaire, de nouveaux arrêts ont été implantés pour améliorer la desserte des zones d''activités et des nouveaux lotissements.', 'La Ligne 11 Express renforce sa fréquence matinale avec un passage toutes les 15 minutes entre 7h00 et 8h45. La Ligne 20 bénéficie quant à elle d''un tracé optimisé à Colombelles pour fluidifier les correspondances avec le pôle d''échange de la Gare SNCF.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1000&q=80') ON CONFLICT ("id") DO UPDATE SET "title"=EXCLUDED."title", "date"=EXCLUDED."date", "category"=EXCLUDED."category", "badge"=EXCLUDED."badge", "badgeColor"=EXCLUDED."badgeColor", "author"=EXCLUDED."author", "summary"=EXCLUDED."summary", "content"=EXCLUDED."content", "image"=EXCLUDED."image";
