-- ============================================================================
-- HISTO14BUS - SCHEMA & DONNÉES SUPABASE (POSTGRESQL)
-- Exécutez ce script dans Supabase -> SQL Editor -> New Query -> Run
-- ============================================================================

-- 1. TABLE VEHICULES (FLEET)
CREATE TABLE IF NOT EXISTS public.vehicles (
    "id" TEXT PRIMARY KEY,
    "number" TEXT NOT NULL,
    "brand" TEXT,
    "model" TEXT,
    "type" TEXT,
    "gabarit" TEXT,
    "network" TEXT,
    "operator" TEXT,
    "depot" TEXT,
    "energy" TEXT,
    "status" TEXT,
    "plate" TEXT,
    "registration" TEXT,
    "deliveryDate" TEXT,
    "inServiceDate" TEXT,
    "serviceDate" TEXT,
    "capacity" TEXT,
    "doors" INTEGER,
    "length" TEXT,
    "livery" TEXT,
    "lines" JSONB DEFAULT '[]'::jsonb,
    "equipments" JSONB DEFAULT '[]'::jsonb,
    "photo" TEXT,
    "history" JSONB DEFAULT '[]'::jsonb,
    "notes" TEXT,
    "created_at" TIMESTAMPTZ DEFAULT NOW(),
    "updated_at" TIMESTAMPTZ DEFAULT NOW()
);

-- 2. TABLE LIGNES
CREATE TABLE IF NOT EXISTS public.lines (
    "id" TEXT PRIMARY KEY,
    "number" TEXT NOT NULL,
    "name" TEXT,
    "type" TEXT,
    "category" TEXT,
    "color" TEXT,
    "textColor" TEXT,
    "terminusA" TEXT,
    "terminusB" TEXT,
    "stationsCount" INTEGER,
    "stopsCount" INTEGER,
    "frequency" TEXT,
    "validFrom" TEXT,
    "validUntil" TEXT,
    "planDate" TEXT,
    "planUrl" TEXT,
    "schedulePdfUrl" TEXT,
    "connections" JSONB DEFAULT '{}'::jsonb,
    "accessibility" JSONB DEFAULT '[]'::jsonb,
    "stops" JSONB DEFAULT '[]'::jsonb,
    "description" TEXT,
    "rollingStock" TEXT,
    "keyConnections" JSONB DEFAULT '[]'::jsonb,
    "history" TEXT,
    "created_at" TIMESTAMPTZ DEFAULT NOW(),
    "updated_at" TIMESTAMPTZ DEFAULT NOW()
);

-- 3. TABLE ACTUALITÉS (MAG_ARTICLES)
CREATE TABLE IF NOT EXISTS public.news (
    "id" TEXT PRIMARY KEY,
    "title" TEXT NOT NULL,
    "date" TEXT,
    "category" TEXT,
    "badge" TEXT,
    "badgeColor" TEXT,
    "author" TEXT,
    "summary" TEXT,
    "content" TEXT,
    "image" TEXT,
    "created_at" TIMESTAMPTZ DEFAULT NOW(),
    "updated_at" TIMESTAMPTZ DEFAULT NOW()
);

-- 4. TABLE MOUVEMENTS
CREATE TABLE IF NOT EXISTS public.movements (
    "id" TEXT PRIMARY KEY,
    "vehicleNumber" TEXT NOT NULL,
    "model" TEXT,
    "type" TEXT,
    "date" TEXT,
    "origin" TEXT,
    "destination" TEXT,
    "details" TEXT,
    "created_at" TIMESTAMPTZ DEFAULT NOW(),
    "updated_at" TIMESTAMPTZ DEFAULT NOW()
);

-- 5. TABLE GALERIE PHOTOS
CREATE TABLE IF NOT EXISTS public.gallery (
    "id" TEXT PRIMARY KEY,
    "title" TEXT NOT NULL,
    "author" TEXT,
    "location" TEXT,
    "url" TEXT,
    "date" TEXT,
    "created_at" TIMESTAMPTZ DEFAULT NOW(),
    "updated_at" TIMESTAMPTZ DEFAULT NOW()
);

-- ============================================================================
-- ACTIVATION DE LA SÉCURITÉ ROW LEVEL SECURITY (RLS) ET POLITIQUES D'ACCÈS
-- ============================================================================
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public select vehicles" ON public.vehicles;
CREATE POLICY "Public select vehicles" ON public.vehicles FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public insert vehicles" ON public.vehicles;
CREATE POLICY "Public insert vehicles" ON public.vehicles FOR INSERT WITH CHECK (true);
DROP POLICY IF EXISTS "Public update vehicles" ON public.vehicles;
CREATE POLICY "Public update vehicles" ON public.vehicles FOR UPDATE USING (true);
DROP POLICY IF EXISTS "Public delete vehicles" ON public.vehicles;
CREATE POLICY "Public delete vehicles" ON public.vehicles FOR DELETE USING (true);

ALTER TABLE public.lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public select lines" ON public.lines;
CREATE POLICY "Public select lines" ON public.lines FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public insert lines" ON public.lines;
CREATE POLICY "Public insert lines" ON public.lines FOR INSERT WITH CHECK (true);
DROP POLICY IF EXISTS "Public update lines" ON public.lines;
CREATE POLICY "Public update lines" ON public.lines FOR UPDATE USING (true);
DROP POLICY IF EXISTS "Public delete lines" ON public.lines;
CREATE POLICY "Public delete lines" ON public.lines FOR DELETE USING (true);

ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public select news" ON public.news;
CREATE POLICY "Public select news" ON public.news FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public insert news" ON public.news;
CREATE POLICY "Public insert news" ON public.news FOR INSERT WITH CHECK (true);
DROP POLICY IF EXISTS "Public update news" ON public.news;
CREATE POLICY "Public update news" ON public.news FOR UPDATE USING (true);
DROP POLICY IF EXISTS "Public delete news" ON public.news;
CREATE POLICY "Public delete news" ON public.news FOR DELETE USING (true);

ALTER TABLE public.movements ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public select movements" ON public.movements;
CREATE POLICY "Public select movements" ON public.movements FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public insert movements" ON public.movements;
CREATE POLICY "Public insert movements" ON public.movements FOR INSERT WITH CHECK (true);
DROP POLICY IF EXISTS "Public update movements" ON public.movements;
CREATE POLICY "Public update movements" ON public.movements FOR UPDATE USING (true);
DROP POLICY IF EXISTS "Public delete movements" ON public.movements;
CREATE POLICY "Public delete movements" ON public.movements FOR DELETE USING (true);

ALTER TABLE public.gallery ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public select gallery" ON public.gallery;
CREATE POLICY "Public select gallery" ON public.gallery FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public insert gallery" ON public.gallery;
CREATE POLICY "Public insert gallery" ON public.gallery FOR INSERT WITH CHECK (true);
DROP POLICY IF EXISTS "Public update gallery" ON public.gallery;
CREATE POLICY "Public update gallery" ON public.gallery FOR UPDATE USING (true);
DROP POLICY IF EXISTS "Public delete gallery" ON public.gallery;
CREATE POLICY "Public delete gallery" ON public.gallery FOR DELETE USING (true);

-- Vues synonymes en français
CREATE OR REPLACE VIEW public.vehicules AS SELECT * FROM public.vehicles;
CREATE OR REPLACE VIEW public.lignes AS SELECT * FROM public.lines;
CREATE OR REPLACE VIEW public.mag_articles AS SELECT * FROM public.news;
CREATE OR REPLACE VIEW public.mouvements AS SELECT * FROM public.movements;
CREATE OR REPLACE VIEW public.galerie AS SELECT * FROM public.gallery;

